from collections import deque
class Solution:
    def minOperations(self, s1: str, s2: str) -> int:
        start, target = s1, s2
        if start == target:
            return 0
        q, seen = deque([(start, 0)]), {start}
        while q:
            cur, d = q.popleft()
            for i, ch in enumerate(cur):
                if ch == '0':
                    nxt = cur[:i] + '1' + cur[i+1:]
                    if nxt == target:
                        return d + 1
                    if nxt not in seen:
                        seen.add(nxt)
                        q.append((nxt, d + 1))
            for i in range(len(cur) - 1):
                if cur[i] == '1' and cur[i+1] == '1':
                    nxt = cur[:i] + '00' + cur[i+2:]
                    if nxt == target:
                        return d + 1
                    if nxt not in seen:
                        seen.add(nxt)
                        q.append((nxt, d + 1))
        return -1

