class Solution {
public:
    int minOperations(string s1, string s2) {
        if (s1 == s2) return 0;
        queue<pair<string,int>> q;
        unordered_set<string> seen{s1};
        q.push({s1, 0});
        while (!q.empty()) {
            auto [cur, d] = q.front(); q.pop();
            string nxt = cur;
            for (int i = 0; i < (int)cur.size(); i++) {
                if (cur[i] == '0') {
                    nxt[i] = '1';
                    if (nxt == s2) return d + 1;
                    if (!seen.count(nxt)) { seen.insert(nxt); q.push({nxt, d + 1}); }
                    nxt[i] = '0';
                }
            }
            for (int i = 0; i + 1 < (int)cur.size(); i++) {
                if (cur[i] == '1' && cur[i+1] == '1') {
                    nxt[i] = nxt[i+1] = '0';
                    if (nxt == s2) return d + 1;
                    if (!seen.count(nxt)) { seen.insert(nxt); q.push({nxt, d + 1}); }
                    nxt[i] = nxt[i+1] = '1';
                }
            }
        }
        return -1;
    }
};

