import java.util.*;
class Solution {
    public int minOperations(String s1, String s2) {
        if (s1.equals(s2)) return 0;
        Deque<Object[]> q = new ArrayDeque<>();
        Set<String> seen = new HashSet<>(Set.of(s1));
        q.add(new Object[]{s1, 0});
        while (!q.isEmpty()) {
            Object[] top = q.poll();
            String cur = (String) top[0];
            int d = (Integer) top[1];
            char[] a = cur.toCharArray();
            for (int i = 0; i < a.length; i++) {
                if (a[i] == '0') {
                    a[i] = '1';
                    String nxt = new String(a);
                    if (nxt.equals(s2)) return d + 1;
                    if (seen.add(nxt)) q.add(new Object[]{nxt, d + 1});
                    a[i] = '0';
                }
            }
            for (int i = 0; i + 1 < a.length; i++) {
                if (a[i] == '1' && a[i+1] == '1') {
                    a[i] = a[i+1] = '0';
                    String nxt = new String(a);
                    if (nxt.equals(s2)) return d + 1;
                    if (seen.add(nxt)) q.add(new Object[]{nxt, d + 1});
                    a[i] = a[i+1] = '1';
                }
            }
        }
        return -1;
    }
}

