class Solution:
    def minOperations(self, s1: str, s2: str) -> int:
        INF = float('inf')
        n = len(s1)
        dp = [INF, INF]
        dp[int(s1[0])] = 0
        for i in range(n - 1):
            nxt = int(s1[i + 1])
            ndp = [INF, INF]
            for v in range(2):
                cur = dp[v]
                if cur == INF:
                    continue
                t = int(s2[i])
                if v == t:
                    ndp[nxt] = min(ndp[nxt], cur)
                elif v == 0:
                    ndp[nxt] = min(ndp[nxt], cur + 1)
                cost = cur + (1 - v) + (1 - nxt) + 1 + t
                ndp[0] = min(ndp[0], cost)
            dp = ndp
        return dp[int(s2[-1])] if dp[int(s2[-1])] < INF else -1

