class Solution {
public:
    int minOperations(string s1, string s2) {
        const long long INF = LLONG_MAX / 2;
        int n = s1.size();
        vector<long long> dp(2, INF);
        dp[s1[0] - '0'] = 0;
        for (int i = 0; i + 1 < n; i++) {
            int nxt = s1[i + 1] - '0', t = s2[i] - '0';
            vector<long long> ndp(2, INF);
            for (int v = 0; v < 2; v++) {
                long long cur = dp[v];
                if (cur >= INF) continue;
                if (v == t) ndp[nxt] = min(ndp[nxt], cur);
                else if (v == 0) ndp[nxt] = min(ndp[nxt], cur + 1);
                long long cost = cur + (1 - v) + (1 - nxt) + 1 + t;
                ndp[0] = min(ndp[0], cost);
            }
            dp = ndp;
        }
        long long ans = dp[s2.back() - '0'];
        return ans >= INF ? -1 : (int)ans;
    }
};

