class Solution {
    public int minOperations(String s1, String s2) {
        final long INF = Long.MAX_VALUE / 2;
        int n = s1.length();
        long[] dp = {INF, INF};
        dp[s1.charAt(0) - '0'] = 0;
        for (int i = 0; i + 1 < n; i++) {
            int nxt = s1.charAt(i + 1) - '0', t = s2.charAt(i) - '0';
            long[] ndp = {INF, INF};
            for (int v = 0; v < 2; v++) {
                long cur = dp[v];
                if (cur >= INF) continue;
                if (v == t) ndp[nxt] = Math.min(ndp[nxt], cur);
                else if (v == 0) ndp[nxt] = Math.min(ndp[nxt], cur + 1);
                long cost = cur + (1 - v) + (1 - nxt) + 1 + t;
                ndp[0] = Math.min(ndp[0], cost);
            }
            dp = ndp;
        }
        long ans = dp[s2.charAt(n - 1) - '0'];
        return ans >= INF ? -1 : (int) ans;
    }
}

